 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    beams = {}
    # Each solid 3x3 square projects a full horizontal and vertical line
    # through its center. Conflicting lines cancel at their intersection.
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                cr, cc = r + 1, c + 1
                for x in range(w):
                    beams.setdefault((cr, x), set()).add(color)
                for y in range(h):
                    beams.setdefault((y, cc), set()).add(color)
    out = [row[:] for row in grid]
    for (r, c), colors in beams.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
